76	  );
77	  process.stdout.write(`Options:\n`);
78	  process.stdout.write(`  -h, --help                Show help\n`);
79	  process.stdout.write(`  -f, --force               Pass --yes to bumpp\n`);
80	  process.stdout.write(`  -p, --package <spec>      Package spec (repeatable)\n`);
81	  process.stdout.write(`  --alpha | --beta | --rc | --release-candidate\n`);
82	  process.stdout.write(
