94	function parseCliArgs(argv: string[]): CliOptions {
95	  const packageFlagSpecs: string[] = [];
96	  const positionalSpecs: string[] = [];
97	  let force = false;
98	  let help = false;
99	  let channel: PreReleaseChannel | undefined;
100	
101	  for (let i = 0; i < argv.length; i += 1) {
102	    const arg = argv[i];
103	
104	    if (arg === "-h" || arg === "--help") {
105	      help = true;
106	      continue;
107	    }
108	
109	    if (arg === "-f" || arg === "--force") {
110	      force = true;
111	      continue;
112	    }
113	
114	    if (arg === "--target") {
115	      throw new Error(
116	        "--target is no longer supported. Use -p/--package or positional package specs.",
117	      );
118	    }
