130	    if (arg === "-p" || arg === "--package") {
131	      const value = argv[i + 1];
132	      if (!value || value.startsWith("-")) {
133	        throw new Error(`${arg} requires a package spec value.`);
134	      }
135	      packageFlagSpecs.push(value);
136	      i += 1;
