144	      }
145	      packageFlagSpecs.push(value);
146	      continue;
147	    }
148	
149	    if (arg.startsWith("-")) {
150	      throw new Error(`Unknown option: ${arg}`);
151	    }
152	
153	    positionalSpecs.push(arg);
154	  }
155	
156	  if (packageFlagSpecs.length > 0 && positionalSpecs.length > 0) {
157	    throw new Error("Do not mix -p/--package with positional package specs.");
158	  }
159	
160	  return {
161	    help,
162	    force,
163	    channel,
164	    packageSpecs: packageFlagSpecs.length > 0 ? packageFlagSpecs : positionalSpecs,
