313	}
314	
315	async function writePackageChangelog(
316	  rootDir: string,
317	  pkg: WorkspacePackage,
318	  version: string,
319	  line: string = DEFAULT_CHANGELOG_LINE,
320	) {
321	  const changelogPath = path.join(rootDir, pkg.path, "CHANGELOG.md");
322	  const section = [`## ${version}`, "", "### Changed", "", `- ${line}`, ""].join("\n");
323	
324	  let current = "";
325	  try {
326	    current = await fs.readFile(changelogPath, "utf8");
327	  } catch {
328	    current = "# CHANGELOG\n\n";
329	  }
330	
331	  const hasSection = new RegExp(
332	    `^##\\s+\\[?v?${version.replace(/[.*+?^${}()|[\\]\\]/g, "\\$&")}\\]?\\b`,
333	    "m",
334	  ).test(current);
335	  if (hasSection) {
336	    return;
337	  }
338	
339	  const next = current.startsWith("# CHANGELOG")
340	    ? current.replace(/^# CHANGELOG\s*\n?/m, `# CHANGELOG\n\n${section}`)
341	    : `# CHANGELOG\n\n${section}${current}`;
342	
343	  await fs.writeFile(changelogPath, next);
344	}
345	
346	function collectWorkspaceDependencyVersionChanges(
347	  pkg: WorkspacePackage,
348	  previousByName: Map<string, WorkspacePackage>,
349	  nextByName: Map<string, WorkspacePackage>,
350	): DependencyVersionChange[] {
351	  const changes: DependencyVersionChange[] = [];
352	
353	  for (const depName of [...pkg.workspaceDeps].sort((a, b) => a.localeCompare(b))) {
354	    const previous = previousByName.get(depName);
355	    const next = nextByName.get(depName);
356	    if (!previous || !next) {
357	      continue;
358	    }
359	    if (previous.version === next.version) {
360	      continue;
361	    }
362	
363	    changes.push({
364	      name: depName,
365	      from: previous.version,
366	      to: next.version,
367	    });
368	  }
369	
370	  return changes;
371	}
372	
373	function buildDependencyChangelogLine(changes: DependencyVersionChange[]): string {
374	  if (changes.length === 0) {
375	    return DEFAULT_CHANGELOG_LINE;
376	  }
377	
378	  const lines = [
379	    "Updated internal workspace dependencies:",
380	    ...changes.map((change) => `  - ${change.name}: ${change.from} -> ${change.to}`),
381	  ];
382	  return lines.join("\n");
383	}
384	
385	function packageHasScript(rootDir: string, pkgPath: string, scriptName: string): boolean {
386	  try {
387	    const raw = spawnSync("cat", [path.join(rootDir, pkgPath, "package.json")], {
388	      encoding: "utf8",
389	      shell: false,
390	      stdio: ["ignore", "pipe", "ignore"],
391	    }).stdout;
392	    const manifest = readJsonObject<PackageManifestScripts>(raw);
393	    return typeof manifest.scripts?.[scriptName] === "string";
394	  } catch {
395	    return false;
396	  }
397	}
398	
399	function runFilteredTask(
400	  rootDir: string,
401	  taskName: string,
402	  extraArgs: string[],
403	  releaseNames: string[],
404	  byName: Map<string, WorkspacePackage>,
405	) {
406	  const supported = releaseNames.filter((name) => {
407	    const pkg = byName.get(name);
408	    if (!pkg) {
409	      return false;
410	    }
411	    return packageHasScript(rootDir, pkg.path, taskName);
412	  });
413	
414	  if (supported.length === 0) {
415	    process.stdout.write(`Skipping task ${taskName}: no release packages define it.\n`);
416	    return;
417	  }
418	
419	  run("vp", ["run", ...supported.flatMap((name) => ["-F", name]), taskName, ...extraArgs], {
420	    cwd: rootDir,
421	  });
422	}
423	
424	interface RunOptions {
425	  capture?: boolean;
426	  allowFailure?: boolean;
427	  cwd?: string;
428	}
429	
430	function run(command: string, args: string[], options: RunOptions = {}) {
431	  const result = spawnSync(command, args, {
432	    stdio: options.capture ? ["ignore", "pipe", "pipe"] : "inherit",
433	    encoding: "utf8",
434	    shell: false,
435	    cwd: options.cwd,
436	  });
437	
438	  if (result.status !== 0 && !options.allowFailure) {
439	    const stderr = result.stderr?.trim();
440	    throw new Error(
441	      stderr && stderr.length > 0
442	        ? `${command} ${args.join(" ")} failed: ${stderr}`
443	        : `${command} ${args.join(" ")} failed with exit code ${result.status}`,
444	    );
445	  }
446	
447	  return result;
448	}
449	
450	function ensureCleanWorktree(rootDir: string) {
451	  const result = run("git", ["status", "--porcelain"], { capture: true, cwd: rootDir });
452	  const dirty = result.stdout.trim();
453	  if (dirty.length > 0) {
454	    throw new Error(
455	      "Refusing automated release cut with a dirty git worktree. Commit or stash pending changes first.",
456	    );
457	  }
458	}
459	
460	async function main() {
461	  const cli = parseCliArgs(process.argv.slice(2));
462	
463	  if (cli.help) {
464	    printHelp();
465	    return;
466	  }
467	
468	  ensureNoNestedVpRun();
469	
470	  if (cli.packageSpecs.length === 0) {
471	    throw new Error("Missing package spec. Example: vpr release -p components@1.2.3");
472	  }
473	
474	  const initialWorkspace = await loadWorkspacePackages();
475	  const rootDir = initialWorkspace.rootDir;
476	  ensureCleanWorktree(rootDir);
477	  const requests = await resolveRequestedVersions(
478	    cli.packageSpecs,
479	    initialWorkspace.byName,
480	    cli.channel,
481	  );
482	  const requestedNames = requests.map((entry) => entry.packageName);
483	
484	  const reverse = buildReverseDependencyMap(initialWorkspace.packages);
485	  const releaseNames = mergeReleaseSet(requestedNames, initialWorkspace.byName, reverse)
486	    .map((name) => initialWorkspace.byName.get(name))
487	    .filter((pkg): pkg is WorkspacePackage => Boolean(pkg))
488	    .map((pkg) => pkg.name)
489	    .sort((a, b) => a.localeCompare(b));
490	
491	  const requestByName = new Map(requests.map((entry) => [entry.packageName, entry]));
492	  const nextVersionByName = new Map<string, string>();
493	  for (const name of releaseNames) {
494	    const pkg = initialWorkspace.byName.get(name);
495	    if (!pkg) {
496	      continue;
497	    }
498	    const requested = requestByName.get(name);
499	    nextVersionByName.set(name, requested ? requested.version : bumpPatch(pkg.version));
500	  }
501	
502	  const releasePackageJsonFiles = releaseNames.map((name) => {
503	    const pkg = initialWorkspace.byName.get(name);
504	    if (!pkg) {
505	      throw new Error(`Release set references unknown package: ${name}`);
506	    }
507	    return `${pkg.path}/package.json`;
508	  });
509	
510	  const publishableReleaseNames = releaseNames.filter((name) =>
511	    isPublishablePackage(initialWorkspace.byName.get(name)),
512	  );
513	  const publishableReleaseFilters = publishableReleaseNames.flatMap((name) => ["-F", name]);
514	
515	  process.stdout.write(`Requested packages: ${requestedNames.join(", ")}\n`);
516	  process.stdout.write(`Release set (${releaseNames.length}):\n`);
517	  for (const name of releaseNames) {
518	    process.stdout.write(`- ${name} -> ${nextVersionByName.get(name) ?? "(unchanged)"}\n`);
519	  }
520	
521	  // Scope release gates to the computed release set only.
522	  runFilteredTask(rootDir, "build", [], releaseNames, initialWorkspace.byName);
523	  runFilteredTask(rootDir, "check", ["--fix"], releaseNames, initialWorkspace.byName);
524	  runFilteredTask(rootDir, "test", [], releaseNames, initialWorkspace.byName);
525	
526	  if (
527	    releaseNames.includes("@pantoken/components") ||
528	    releaseNames.includes("@pantoken/web-components")
529	  ) {
530	    run("vp", ["run", "lint:css"], { cwd: rootDir });
531	    run("vp", ["run", "lint:js"], { cwd: rootDir });
532	  }
533	
534	  if (publishableReleaseNames.length > 0) {
535	    run("vp", ["exec", ...publishableReleaseFilters, "publint"], { cwd: rootDir });
536	    run(
537	      "vp",
538	      [
539	        "exec",
540	        ...publishableReleaseFilters,
541	        "attw",
542	        "--pack",
543	        "--profile",
544	        "strict",
545	        "--no-emoji",
546	        "--ignore-rules",
547	        "no-resolution",
548	        "cjs-resolves-to-esm",
549	      ],
550	      { cwd: rootDir },
551	    );
552	  } else {
553	    process.stdout.write("Skipping publint/attw: release set has no publishable packages.\n");
554	  }
555	
556	  // Use deterministic versions per package by invoking bumpp per manifest.
557	  for (const name of releaseNames) {
558	    const pkg = initialWorkspace.byName.get(name);
559	    const version = nextVersionByName.get(name);
560	    if (!pkg || !version) {
561	      continue;
562	    }
563	
564	    const args = [
565	      "bumpp",
566	      `${pkg.path}/package.json`,
567	      "--print-commits",
568	      "--no-commit",
569	      "--no-tag",
570	      "--no-push",
571	      "--release",
572	      version,
573	    ];
574	
575	    if (cli.force) {
576	      args.push("--yes");
577	    }
578	
579	    run("vpx", args, { cwd: rootDir });
580	  }
581	
582	  const refreshedWorkspace = await loadWorkspacePackages();
583	  const refreshedRequests = requestedNames.map((name) => {
584	    const pkg = refreshedWorkspace.byName.get(name);
585	    if (!pkg) {
586	      throw new Error(`Unable to read bumped version for ${name}`);
587	    }
588	    return { name, version: pkg.version };
589	  });
590	
591	  const primary = refreshedRequests[0];
592	  if (!primary) {
593	    throw new Error("No requested packages resolved after bump.");
594	  }
595	
596	  const changedChangelogFiles: string[] = [];
597	  for (const name of releaseNames) {
598	    const pkg = refreshedWorkspace.byName.get(name);
599	    const version = pkg?.version;
600	    if (!pkg || !version) {
601	      continue;
602	    }
603	
604	    const depChanges = collectWorkspaceDependencyVersionChanges(
605	      pkg,
606	      initialWorkspace.byName,
607	      refreshedWorkspace.byName,
608	    );
609	    const changelogLine = buildDependencyChangelogLine(depChanges);
610	    await writePackageChangelog(rootDir, pkg, version, changelogLine);
611	    changedChangelogFiles.push(`${pkg.path}/CHANGELOG.md`);
612	  }
613	
614	  const planTarget = normalizePantokenPackageName(primary.name);
615	  const planVersion = primary.version;
616	
617	  const tags = refreshedRequests.map(
618	    (entry) => `${normalizePantokenPackageName(entry.name)}@v${entry.version}`,
619	  );
620	
621	  run(
622	    "node",
623	    [
624	      "scripts/release/plan-package-release.ts",
625	      "--target",
626	      planTarget,
627	      "--version",
628	      planVersion,
629	      "--json",
630	      ".release-plan.json",
631	      "--publish-list",
632	      ".release-packages.txt",
633	      "--markdown",
634	      ".release-plan.md",
635	    ],
636	    { cwd: rootDir },
637	  );
638	
639	  run(
640	    "node",
641	    [
642	      "scripts/release/build-root-changelog.ts",
643	      "--plan",
644	      ".release-plan.json",
645	      "--out",
646	      "CHANGELOG.md",
647	    ],
648	    { cwd: rootDir },
649	  );
650	
651	  run(
652	    "git",
653	    [
654	      "add",
655	      ...releasePackageJsonFiles,
656	      ...changedChangelogFiles,
657	      "CHANGELOG.md",
658	      ".release-plan.json",
659	      ".release-packages.txt",
660	      ".release-plan.md",
661	    ],
662	    { cwd: rootDir },
663	  );
664	
665	  run("git", ["commit", "-m", `release: ${tags.join(", ")}`], { cwd: rootDir });
666	  for (const tag of tags) {
667	    run("git", ["tag", tag], { cwd: rootDir });
668	  }
669	  run("git", ["push"], { cwd: rootDir });
670	  for (const tag of tags) {
671	    run("git", ["push", "origin", tag], { cwd: rootDir });
672	  }
673	
674	  process.stdout.write(`Release cut complete: ${tags.join(", ")}\n`);
675	}
676	
677	if (isDirectExecution(import.meta.url)) {
678	  main().catch((error) => {
679	    console.error(error instanceof Error ? error.message : String(error));
680	    process.exitCode = 1;
681	  });
682	}
683	
684	export {
685	  DEFAULT_CHANGELOG_LINE,
686	  buildDependencyChangelogLine,
687	  bumpPatch,
688	  collectWorkspaceDependencyVersionChanges,
689	  ensureNoNestedVpRun,
690	  parseCliArgs,
691	  resolveRequestedVersions,
692	  withPreRelease,
693	  writePackageChangelog,
694	};
