  cache: true,
  tasks: {
    // `ready` is a task DAG, not a serial `&&` chain: `build:all` runs once, then the independent
    // gates fan out concurrently. `command: "true"` makes `ready` a pure aggregator whose only job is
    // to pull its `dependsOn`. Everything that needs generated output funnels through `build:all` — the
    // single generation path — so no two nodes run the component codegen at once (a `vp run -r build`
    // and a bare `@pantoken/components#generate` writing the same `generated/` dir would race).
    "build:all": {
      command: "vp run -r build",
    },
    "check:all": {
      command: "vp check",
      dependsOn: ["build:all"],
    },
    "test:all": {
      command: "vp run -r test",
      dependsOn: ["build:all"],
    },
    "validate:generated:only": {
      command: "vp run @pantoken/validate-generated#validate",
      dependsOn: ["build:all"],
