1	import fs from "node:fs/promises";
2	import path from "node:path";
3	
4	type ManifestDeps = Record<string, unknown>;
5	
6	interface PackageManifest {
7	  name?: unknown;
8	  version?: unknown;
9	  private?: unknown;
10	  dependencies?: ManifestDeps;
11	  optionalDependencies?: ManifestDeps;
12	  peerDependencies?: ManifestDeps;
13	}
14	
15	export interface WorkspacePackage {
16	  name: string;
17	  path: string;
18	  version: string;
19	  private: boolean;
20	  workspaceDeps: Set<string>;
21	}
22	
23	export interface WorkspacePackages {
24	  rootDir: string;
25	  packages: WorkspacePackage[];
26	  byName: Map<string, WorkspacePackage>;
27	}
28	
29	export interface ParsedPackageTag {
30	  packageName: string;
31	  version: string;
32	}
33	
34	export interface ParsedRequestedPackageSpec {
35	  raw: string;
36	  packageName: string;
37	  versionOrChannel?: string;
38	}
39	
40	const WORKSPACE_ROOT = path.resolve(new URL("../../", import.meta.url).pathname);
41	
42	const PACKAGE_ROOTS = [
43	  "docs",
44	  "packages",
45	  "formats",
46	  "platforms",
47	  "renderers",
48	  "bundlers",
49	  "design",
50	  "ai",
51	  "plugins/pantoken",
52	  "plugins/postcss",
53	  "plugins/typedoc",
54	  "plugins/vite",
55	  "tools",
56	];
57	
58	const WORKSPACE_PROTOCOL = "workspace:";
59	
60	const toPosix = (value: string): string => value.split(path.sep).join("/");
61	
62	async function listChildDirs(basePath: string): Promise<string[]> {
63	  let entries: import("node:fs").Dirent[] = [];
64	
65	  try {
66	    entries = await fs.readdir(basePath, { withFileTypes: true });
67	  } catch {
68	    return [];
69	  }
70	
71	  return entries.filter((entry) => entry.isDirectory()).map((entry) => entry.name);
72	}
73	
74	function collectWorkspaceDeps(manifest: PackageManifest): Set<string> {
75	  const buckets = [
76	    manifest.dependencies ?? {},
77	    manifest.optionalDependencies ?? {},
78	    manifest.peerDependencies ?? {},
79	  ];
80	
81	  const deps = new Set<string>();
82	
83	  for (const bucket of buckets) {
84	    for (const [depName, depRange] of Object.entries(bucket)) {
85	      if (typeof depRange === "string" && depRange.startsWith(WORKSPACE_PROTOCOL)) {
86	        deps.add(depName);
87	      }
88	    }
89	  }
90	
91	  return deps;
92	}
93	
94	async function readWorkspacePackage(relDir: string): Promise<WorkspacePackage | null> {
95	  const pkgPath = path.join(WORKSPACE_ROOT, relDir, "package.json");
96	
97	  let raw;
98	  try {
99	    raw = await fs.readFile(pkgPath, "utf8");
100	  } catch {
101	    return null;
102	  }
103	
104	  let manifest: PackageManifest;
105	  try {
106	    manifest = JSON.parse(raw) as PackageManifest;
107	  } catch {
108	    throw new Error(`Invalid JSON in ${relDir}/package.json`);
109	  }
110	
111	  if (typeof manifest.name !== "string" || manifest.name.length === 0) {
112	    return null;
113	  }
114	
115	  return {
116	    name: manifest.name,
117	    path: relDir,
118	    version: typeof manifest.version === "string" ? manifest.version : "0.0.0",
119	    private: Boolean(manifest.private),
120	    workspaceDeps: collectWorkspaceDeps(manifest),
121	  };
122	}
123	
124	export async function loadWorkspacePackages(): Promise<WorkspacePackages> {
125	  const packages: WorkspacePackage[] = [];
126	  const seenPaths = new Set<string>();
127	
128	  for (const root of PACKAGE_ROOTS) {
129	    const absRoot = path.join(WORKSPACE_ROOT, root);
130	    const children = await listChildDirs(absRoot);
131	    const candidates = [root, ...children.map((child) => toPosix(path.join(root, child)))];
132	
133	    for (const relDir of candidates) {
134	      if (seenPaths.has(relDir)) {
135	        continue;
136	      }
137	      seenPaths.add(relDir);
138	
139	      const workspacePackage = await readWorkspacePackage(relDir);
140	      if (!workspacePackage) {
141	        continue;
142	      }
143	
144	      packages.push(workspacePackage);
145	    }
146	  }
147	
148	  const byName = new Map(packages.map((pkg) => [pkg.name, pkg]));
149	
150	  return {
151	    rootDir: WORKSPACE_ROOT,
152	    packages,
153	    byName,
154	  };
155	}
156	
157	export function buildReverseDependencyMap(packages: WorkspacePackage[]): Map<string, Set<string>> {
158	  const reverse = new Map<string, Set<string>>();
159	
160	  for (const pkg of packages) {
161	    if (!reverse.has(pkg.name)) {
162	      reverse.set(pkg.name, new Set());
163	    }
164	  }
165	
166	  for (const pkg of packages) {
167	    for (const dep of pkg.workspaceDeps) {
168	      if (!reverse.has(dep)) {
169	        reverse.set(dep, new Set());
170	      }
171	      const dependents = reverse.get(dep);
172	      if (dependents) {
173	        dependents.add(pkg.name);
174	      }
175	    }
176	  }
177	
178	  return reverse;
179	}
180	
181	export function computeReleaseSet(
182	  targetName: string,
183	  byName: Map<string, WorkspacePackage>,
184	  reverseMap: Map<string, Set<string>>,
185	): string[] {
186	  const visited = new Set<string>();
187	  const queue: string[] = [targetName];
188	
189	  while (queue.length > 0) {
190	    const current = queue.shift();
191	    if (!current) {
192	      continue;
193	    }
194	    if (visited.has(current)) {
195	      continue;
196	    }
197	
198	    visited.add(current);
199	
200	    const dependents = reverseMap.get(current);
201	    if (!dependents) {
202	      continue;
203	    }
204	
205	    for (const dependent of dependents) {
206	      if (!visited.has(dependent)) {
207	        queue.push(dependent);
208	      }
209	    }
210	  }
211	
212	  const metaPackage = byName.get("@pantoken/pantoken");
213	  const targetPackage = byName.get(targetName);
214	  if (metaPackage && targetName !== "@pantoken/pantoken" && !targetPackage?.private) {
215	    const touchesMetaSurface = [...visited].some((name) => metaPackage.workspaceDeps.has(name));
216	
217	    if (touchesMetaSurface) {
218	      visited.add(metaPackage.name);
219	    }
220	  }
221	
222	  return [...visited].sort((a, b) => a.localeCompare(b));
223	}
224	
225	export function parsePackageTag(tag: string): ParsedPackageTag | null {
226	  const match = /^(@pantoken\/[A-Za-z0-9._-]+)@v(.+)$/.exec(tag);
227	  if (!match) {
228	    return null;
229	  }
230	
231	  return {
232	    packageName: match[1],
233	    version: match[2],
234	  };
235	}
236	
237	export function normalizePantokenPackageName(value: string): string {
238	  if (!value) {
239	    return value;
240	  }
241	
242	  if (value.startsWith("@pantokens/")) {
243	    return value.replace("@pantokens/", "@pantoken/");
244	  }
245	
246	  if (value.startsWith("@pantoken/")) {
247	    return value;
248	  }
249	
250	  if (value.startsWith("@")) {
251	    return value;
252	  }
253	
254	  return `@pantoken/${value}`;
255	}
256	
257	export function parseRequestedPackageSpec(spec: string): ParsedRequestedPackageSpec {
258	  const raw = spec.trim();
259	  if (raw.length === 0) {
260	    throw new Error("Package spec cannot be empty.");
261	  }
262	
263	  const at = raw.lastIndexOf("@");
264	  const hasScopedPrefix = raw.startsWith("@");
265	
266	  // Scoped package names include one leading @ by definition.
267	  const hasVersionPart = at > 0 && (!hasScopedPrefix || at > raw.indexOf("/"));
268	
269	  if (!hasVersionPart) {
270	    return {
271	      raw,
272	      packageName: normalizePantokenPackageName(raw),
273	    };
274	  }
