12	
13	// Files that can affect every package's build/pack output, so a change to any of them widens the
14	// scope to the whole publishable set rather than a subset.
15	const GLOBAL_FILES = new Set([
16	  "package.json",
17	  "pnpm-lock.yaml",
18	  "pnpm-workspace.yaml",
19	  "vite.config.ts",
20	  "tsconfig.json",
21	  "tsconfig.base.json",
22	  ".changeset/config.json",
23	]);
24	
25	export type ChangeScope = "all" | "subset" | "none";
26	
27	export interface ChangedPackagesResult {
28	  scope: ChangeScope;
29	  // Publishable package names to gate, empty unless scope === "subset".
30	  packages: string[];
31	}
32	
33	function toPosix(value: string): string {
34	  return value.split(path.sep).join("/");
35	}
36	
37	/**
38	 * Map a list of changed repo-relative files to the publishable packages a publish gate should cover.
39	 * A change to a global config file returns `scope: "all"` (caller runs the full gate); a change that
40	 * touches no publishable package (docs, tooling, CI) returns `scope: "none"` (caller skips the gate);
41	 * otherwise the directly-changed packages are expanded to include their workspace dependents (whose
42	 * packs/types can break when a dependency changes) and filtered to the publishable set.
43	 */
44	export function resolveChangedPackages(
45	  changedFiles: string[],
46	  packages: WorkspacePackage[],
47	): ChangedPackagesResult {
48	  const normalized = changedFiles.map((file) => toPosix(file.trim())).filter(Boolean);
49	
50	  if (normalized.some((file) => GLOBAL_FILES.has(file))) {
51	    return { scope: "all", packages: [] };
52	  }
53	
54	  // Longest-path-first so a nested package (e.g. plugins/pantoken/logos) wins over its root prefix.
55	  const byPathDepth = [...packages].sort((a, b) => b.path.length - a.path.length);
56	  const directlyChanged = new Set<string>();
57	
58	  for (const file of normalized) {
59	    const owner = byPathDepth.find((pkg) => file === pkg.path || file.startsWith(`${pkg.path}/`));
60	    if (owner) {
61	      directlyChanged.add(owner.name);
62	    }
63	  }
64	
65	  if (directlyChanged.size === 0) {
66	    return { scope: "none", packages: [] };
67	  }
68	
69	  const byName = new Map(packages.map((pkg) => [pkg.name, pkg]));
70	  const reverse = buildReverseDependencyMap(packages);
71	
72	  const expanded = new Set<string>();
73	  for (const name of directlyChanged) {
74	    for (const affected of computeReleaseSet(name, byName, reverse)) {
75	      expanded.add(affected);
76	    }
77	  }
78	
79	  const publishable = [...expanded]
80	    .filter((name) => isPublishablePackage(byName.get(name)))
81	    .sort((a, b) => a.localeCompare(b));
82	
83	  return publishable.length > 0
84	    ? { scope: "subset", packages: publishable }
85	    : { scope: "none", packages: [] };
86	}
