88	function isDirectExecution(metaUrl: string): boolean {
89	  const entry = process.argv[1];
90	  if (!entry) {
91	    return false;
92	  }
93	  return pathToFileURL(path.resolve(entry)).href === metaUrl;
94	}
95	
96	function readArg(flag: string): string | undefined {
97	  const index = process.argv.indexOf(flag);
98	  if (index >= 0 && index + 1 < process.argv.length) {
99	    return process.argv[index + 1];
100	  }
101	  return undefined;
102	}
103	
104	function isUsableBase(ref: string | undefined): ref is string {
105	  return Boolean(ref) && !/^0+$/.test(ref as string);
106	}
107	
108	function gitDiffFiles(base: string): string[] | null {
109	  const result = spawnSync("git", ["diff", "--name-only", `${base}...HEAD`], {
110	    encoding: "utf8",
111	    shell: false,
112	  });
113	  if (result.status !== 0) {
114	    return null;
115	  }
116	  return result.stdout.split("\n").filter(Boolean);
117	}
118	
119	async function main() {
120	  const base = readArg("--base") ?? process.env.CHANGED_BASE;
121	  const { packages } = await loadWorkspacePackages();
122	
123	  // No usable base (new branch, missing ref) → can't diff, so gate the whole set to stay safe.
124	  const changedFiles = isUsableBase(base) ? gitDiffFiles(base) : null;
125	  const result =
126	    changedFiles === null
127	      ? { scope: "all" as const, packages: [] }
128	      : resolveChangedPackages(changedFiles, packages);
129	
130	  if (process.env.GITHUB_OUTPUT) {
131	    const { appendFileSync } = await import("node:fs");
132	    appendFileSync(
133	      process.env.GITHUB_OUTPUT,
134	      `scope=${result.scope}\npackages=${result.packages.join(",")}\ncount=${result.packages.length}\n`,
135	    );
136	  }
137	
138	  process.stdout.write(`${JSON.stringify(result)}\n`);
139	}
140	
141	if (isDirectExecution(import.meta.url)) {
142	  main().catch((error) => {
143	    console.error(error instanceof Error ? error.message : String(error));
144	    process.exitCode = 1;
145	  });
146	}

